<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import Icon from '@/Components/Icon.vue';

const props = defineProps({
    open: { type: Boolean, default: false }, vehicle: { type: Object, required: true }, form: { type: Object, required: true }, success: { type: Boolean, default: false },
});
const emit = defineEmits(['close', 'submit']);
const modal = ref(null); const closeButton = ref(null); const previousFocus = ref(null);
const focusables = () => [...(modal.value?.querySelectorAll('button, input, textarea, select, [href]') || [])].filter((element) => !element.disabled);
const close = () => emit('close');
const handleKeydown = (event) => { if (!props.open) return; if (event.key === 'Escape') { event.preventDefault(); close(); return; } if (event.key !== 'Tab') return; const items = focusables(); if (!items.length) return; const first = items[0]; const last = items[items.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } };
watch(() => props.open, async (open) => { if (open) { previousFocus.value = document.activeElement; document.body.style.overflow = 'hidden'; await nextTick(); closeButton.value?.focus(); } else { document.body.style.overflow = ''; previousFocus.value?.focus?.(); } });
onBeforeUnmount(() => { document.body.style.overflow = ''; });
onMounted(() => window.addEventListener('keydown', handleKeydown));
onBeforeUnmount(() => window.removeEventListener('keydown', handleKeydown));
</script>

<template>
    <Teleport to="body"><Transition name="inquiry-modal"><div v-if="open" class="inquiry-modal-backdrop" @click.self="close"><section ref="modal" class="inquiry-modal" role="dialog" aria-modal="true" aria-labelledby="inquiry-modal-title"><header class="inquiry-modal-header"><div><p class="eyebrow">Vehicle inquiry</p><h2 id="inquiry-modal-title" class="mt-2 text-2xl font-bold">Request information</h2></div><button ref="closeButton" type="button" class="icon-close" aria-label="Close inquiry form" @click="close">×</button></header><div v-if="success" class="inquiry-success"><p class="eyebrow">Request received</p><h3 class="mt-2 text-xl font-bold">Thanks for reaching out.</h3><p class="mt-2 text-sm leading-6 text-text-muted">Our sales team will review your request and contact you soon.</p><button type="button" class="btn-primary mt-6" @click="close">Done</button></div><form v-else class="inquiry-form" @submit.prevent="emit('submit')"><div class="inquiry-vehicle"><img v-if="vehicle.main_image" :src="vehicle.main_image" :alt="vehicle.name" width="96" height="72"><div><p class="text-sm font-bold">{{ vehicle.name }}</p><p class="mt-1 text-sm text-text-muted">{{ vehicle.price }}</p></div></div><div class="grid gap-4 sm:grid-cols-2"><label><span class="form-label">First name</span><input v-model="form.first_name" required autocomplete="given-name" class="form-input-dark"><p v-if="form.errors.first_name" class="form-error">{{ form.errors.first_name }}</p></label><label><span class="form-label">Last name <span class="normal-case tracking-normal">(optional)</span></span><input v-model="form.last_name" autocomplete="family-name" class="form-input-dark"><p v-if="form.errors.last_name" class="form-error">{{ form.errors.last_name }}</p></label><label><span class="form-label">Phone</span><input v-model="form.phone" required type="tel" autocomplete="tel" class="form-input-dark"><p v-if="form.errors.phone" class="form-error">{{ form.errors.phone }}</p></label><label><span class="form-label">Email <span class="normal-case tracking-normal">(optional)</span></span><input v-model="form.email" type="email" autocomplete="email" class="form-input-dark"><p v-if="form.errors.email" class="form-error">{{ form.errors.email }}</p></label></div><label><span class="form-label">Best time to contact <span class="normal-case tracking-normal">(optional)</span></span><input v-model="form.preferred_contact_time" class="form-input-dark"><p v-if="form.errors.preferred_contact_time" class="form-error">{{ form.errors.preferred_contact_time }}</p></label><label><span class="form-label">Message <span class="normal-case tracking-normal">(optional)</span></span><textarea v-model="form.message" rows="4" class="form-input-dark"></textarea><p v-if="form.errors.message" class="form-error">{{ form.errors.message }}</p></label><button class="btn-primary w-full" :disabled="form.processing">{{ form.processing ? 'Sending…' : 'Send request' }} <Icon name="send" /></button></form></section></div></Transition></Teleport>
</template>
